function beApp(){return {routes:[]};}
function beRoute(app,method,path,handler){app.routes.push({method:method.toUpperCase(),path:path,handler:handler});return app;}
function beHandle(app,method,path,req){var r=app.routes.filter(function(x){return x.method===method.toUpperCase()&&x.path===path;})[0];
if(!r)return {status:404,body:'not found'};return r.handler(req||{});}
function beRouteTable(app){return app.routes.map(function(r){return r.method+' '+r.path;});}
